package main
import("context";"net/http";"net/http/httptest";"sync/atomic";"testing";"time")
func TestStatusAndOrder(t *testing.T){s:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){if r.URL.Path=="/bad"{w.WriteHeader(503)}else{w.WriteHeader(204)}}));defer s.Close();r,e:=Probe(context.Background(),[]string{s.URL+"/bad",s.URL},2,time.Second);if e!=nil||r[0].Healthy||!r[1].Healthy||r[0].Status!=503{t.Fatalf("%+v %v",r,e)}}
func TestRedirectNotFollowed(t *testing.T){var calls atomic.Int32;s:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){calls.Add(1);http.Redirect(w,r,"/next",302)}));defer s.Close();r,e:=Probe(context.Background(),[]string{s.URL},1,time.Second);if e!=nil||r[0].Status!=302||r[0].Healthy||calls.Load()!=1{t.Fatalf("%+v %v",r,e)}}
func TestTimeout(t *testing.T){s:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){<-r.Context().Done()}));defer s.Close();r,e:=Probe(context.Background(),[]string{s.URL},1,30*time.Millisecond);if e!=nil||r[0].Error==""||r[0].Healthy{t.Fatalf("%+v %v",r,e)}}
func TestCancellation(t *testing.T){ctx,cancel:=context.WithCancel(context.Background());cancel();r,e:=Probe(ctx,[]string{"http://127.0.0.1:1"},1,time.Second);if e!=nil||r[0].Error==""{t.Fatalf("%+v %v",r,e)}}
func TestWorkerBound(t *testing.T){var current,peak atomic.Int32;s:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){n:=current.Add(1);defer current.Add(-1);for old:=peak.Load();n>old;old=peak.Load(){if peak.CompareAndSwap(old,n){break}};time.Sleep(10*time.Millisecond)}));defer s.Close();urls:=make([]string,12);for i:=range urls{urls[i]=s.URL};r,e:=Probe(context.Background(),urls,3,time.Second);if e!=nil||len(r)!=12||peak.Load()>3||peak.Load()<2{t.Fatalf("peak %d %v",peak.Load(),e)}}
func TestInvalidInputs(t *testing.T){for _,u:=range []string{"file:///tmp/test","ftp://example.com","https://user:pass@example.com","http://","http://example.com/#fragment"}{if _,e:=Probe(context.Background(),[]string{u},1,time.Second);e==nil{t.Fatal(u)}};for _,w:=range []int{0,33}{if _,e:=Probe(context.Background(),[]string{"https://example.com"},w,time.Second);e==nil{t.Fatal(w)}};if _,e:=Probe(context.Background(),nil,1,time.Second);e==nil{t.Fatal("empty endpoints")}}
